{"implementation":"def solve(case):
    nodes = {n['id']: n for n in case['nodes']}
    children = {}
    for n in case['nodes']:
        p = n['parent']
        if p is not None:
            children.setdefault(p, []).append(n['id'])
    required = set(case['required_symbols'])
    removed = []
    removed_set = set()
    sorted_ids = sorted(nodes, key=lambda x: (-nodes[x]['depth'], x))
    for nid in sorted_ids:
        nd = nodes[nid]
        if not nd['removable']:
            continue
        if nd['symbol'] in required:
            continue
        child_list = children.get(nid, [])
        if any(c not in removed_set for c in child_list):
            continue
        removed.append(nid)
        removed_set.add(nid)
    retained = sorted([nid for nid in nodes if nid not in removed_set])
    return {'removed_node_ids': removed, 'retained_node_ids': retained}"}
